mapper.update:
UPDATE meeting_follow_up SET next_reminder_at = #{nextReminderAt}, last_evidence_json = #{evidenceJson},
  revision = revision + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND binding_id = #{bindingId} AND business_key = #{businessKey}
  AND status = 'active' AND (next_reminder_at IS NULL OR next_reminder_at <= #{now})

UPDATE meeting_follow_up SET last_reminder_at = #{now}, reminder_count = reminder_count + 1,
  revision = revision + 1, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND binding_id = #{bindingId} AND business_key = #{businessKey}
